    old=json.loads((HERE/'before/chinese_v20/supplement_aligned_blocks.json').read_text())['blocks'];by={b['id']:b for b in old}
    for key in ['S20_038','S20_080']:
        en=by[key]['en'];zh=by[key]['zh']
        en=en.replace('Notice comparisons used exact paired McNemar tests with Holm correction across 20 contrasts.','All 20 notice comparisons had zero discordant success pairs; their outcomes are reported as identical.').replace('These intervals and qualifications are pointwise, apart from the declared notice-test correction.','These intervals and qualifications are pointwise.').replace('together with all paired binary outcomes and Holm-adjusted exact McNemar tests','together with all paired binary outcomes, which coincide across notice settings')
