    en=by['S20_085']['en'].replace('| 10 | Yes | 672.39 | 677.61 | 5.22 | 0.0000 [-0.0000, 0.0001] |','| 10 | Yes | 672.39 | 677.61 | 5.22 | 0 (numerical; Table 24) |')
